// BAD: Improper Java API usage leading to SQL Injection vulnerability
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServlet extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // vulnerable: direct string concatenation into SQL query allows injection
        String query = "SELECT id FROM users WHERE username = '" + username + "' AND password = '" + password + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
             Statement stmt = conn.createStatement(); // Improper API: Statement with untrusted input
             ResultSet rs = stmt.executeQuery(query)) {

            if (rs.next()) {
                // Login success (but this is unsafe)
            } else {
                // Login failed
            }
        } catch (SQLException e) {
            // Swallowing exception details can hinder incident response
        }
    }
}

***

// GOOD: Proper use of Java API with PreparedStatement and hashed password verification
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.security.MessageDigest;
import java.util.Arrays;

public class LoginServletSafe extends HttpServlet {
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
        String username = req.getParameter("username");
        String password = req.getParameter("password");

        // Input normalization and early validation (defense-in-depth)
        if (username == null || username.length() > 150) {
            // Handle invalid input
            return;
        }

        String sql = "SELECT id, password_hash, password_salt FROM users WHERE username = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "user", "pass");
             PreparedStatement ps = conn.prepareStatement(sql)) {

            // Use parameterized queries to prevent injection
            ps.setString(1, username);

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    byte[] storedHash = rs.getBytes("password_hash");
                    byte[] salt = rs.getBytes("password_salt");

                    // Example: verify password with a proper KDF; shown here with PBKDF2
                    // In production, use a vetted library like BCrypt/Argon2
                    byte[] computed = pbkdf2(password.toCharArray(), salt, 100_000, 256);

                    if (Arrays.equals(storedHash, computed)) {
                        // Login success
                    } else {
                        // Login failed
                    }
                } else {
                    // User not found
                }
            }
        } catch (SQLException e) {
            // Log securely without leaking sensitive data to users
            // logger.warn("Authentication error", e);
        }
    }

    // Minimal PBKDF2 helper using standard API (illustrative)
    private static byte[] pbkdf2(char[] password, byte[] salt, int iterations, int bits) {
        try {
            javax.crypto.SecretKeyFactory skf = javax.crypto.SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256");
            javax.crypto.spec.PBEKeySpec spec = new javax.crypto.spec.PBEKeySpec(password, salt, iterations, bits);
            return skf.generateSecret(spec).getEncoded();
        } catch (Exception e) {
            throw new RuntimeException("KDF failure", e);
        }
    }
}

