// BAD: Using string concatenation with HttpServletRequest.getParameter for SQL builds
// This is vulnerable to SQL injection via crafted "user" parameter.
public void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    String username = req.getParameter("user"); // untrusted input
    // Improper Java API usage: building SQL with string concatenation
    String sql = "SELECT id, role FROM users WHERE username = '" + username + "'"; // vulnerable
    try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "app", "secret");
         Statement stmt = conn.createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {

        if (rs.next()) {
            resp.getWriter().println("Hello " + rs.getString("role"));
        } else {
            resp.getWriter().println("No user");
        }
    } catch (SQLException e) {
        // Leaks internal details to the client
        resp.getWriter().println("DB error: " + e.getMessage()); // also information disclosure
    }
}

/*
Explanation:
- Improper API use: Statement + string concatenation encourages mixing code and data.
- getParameter() returns untrusted data; concatenating it into SQL lets attackers inject ' OR '1'='1, etc.
- Returning raw exception messages exposes internal details.
*/
***
/*
GOOD: Use PreparedStatement with placeholders, validate/normalize input, and avoid leaking internals.
Also limit error messages and set safe defaults.
*/
public void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
    // Validate and normalize untrusted input early
    String username = req.getParameter("user");
    if (username == null || !username.matches("^[A-Za-z0-9_]{1,32}$")) {
        // Reject clearly invalid input without revealing specifics
        resp.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid request.");
        return;
    }

    String sql = "SELECT id, role FROM users WHERE username = ?";

    try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "app", "secret");
         PreparedStatement ps = conn.prepareStatement(sql)) {

        // Proper API usage: bind data separately to avoid SQL injection
        ps.setString(1, username);
        try (ResultSet rs = ps.executeQuery()) {
            if (rs.next()) {
                // Escape output if reflecting user-controlled data into HTML; here we avoid reflecting username
                resp.getWriter().println("Hello " + rs.getString("role"));
            } else {
                resp.getWriter().println("No user");
            }
        }
    } catch (SQLException e) {
        // Log internally; do not leak details to the client
        logDbError(e); // assume this logs to server logs
        resp.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Unexpected error."); // not vulnerable
    }
}

/*
Explanation:
- PreparedStatement separates SQL code from data, preventing injection.
- Input validation reduces unexpected payloads and improves signal-to-noise.
- Generic error messages prevent information disclosure; details go to server logs.
- This demonstrates how improper API usage (Statement + concatenation) leads to vulnerabilities and
  how to fix by using the correct API (PreparedStatement) and safe error handling.
*/

